def main():
    sys.stdout.reconfigure(encoding="utf-8")
    modul = json.load(open(os.path.join(EDEN, "module", "eden_rise", "modul.json"), encoding="utf-8"))
    items = modul["items"]
    zu_lang = [k for k, (_, t) in LORE.items() if len(t) > 240]
    unbekannt = [k for k in LORE if k not in items]
    ohne = [k for k, v in items.items() if k not in LORE and v.get("art") != "beweis" and not re.search(r"_selfie(_\d)?$", k)]
    toene = {}
    for t, _ in LORE.values():
        toene[t] = toene.get(t, 0) + 1
    print("Texte:", len(LORE), "| Toene:", toene, "| zu lang:", zu_lang, "| unbekannt:", unbekannt)
    print("ohne Lore (bleiben wie sie sind):", ohne)
    TON = {"w": "witzig", "h": "wholesome", "f": "frech", "e": "ernst/Lore"}
    gruppen = {}
    for iid, (ton, text) in LORE.items():
        it = items.get(iid, {})
        gruppen.setdefault(it.get("art") or "sonst", []).append(
            {"key": "item:%s.lore" % iid, "feld": "%s · %s" % (it.get("label", iid), TON[ton]),
             "alt": it.get("text") or "(kein Text)", "neu": text, "vertont": False})
    spec = {"id": "item_lore", "titel": "Item-Beschreibungen im Lore-Stil",
            "hinweis": "Ding · Herkunft · Haken, nie wer es liebt. Die Wirkung (Bonus, Heilung) bleibt als eigene Zeile "
                       "und steht hier nicht. OK / Ändern + Notiz.",
            "gruppen": [{"titel": art, "items": liste} for art, liste in gruppen.items()]}
    ziel = os.path.join(EDEN, "docs", "abnahme", "item_lore.json")
    json.dump(spec, open(ziel, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    print("geschrieben:", ziel)


if __name__ == "__main__":
    main()
